// =====================================================================
// ZENTRALE KONFIGURATION – hier pflegen
// Stand: Shopify-Strang, lesend. Mollie + Status-Tabelle bewusst NICHT enthalten.
// =====================================================================
const CONFIG = {
  // --- Zeitfenster ------------------------------------------------------
  fensterMinuten: 4900,
  zeitzone: 'Europe/Berlin',

  // --- Abgrenzung der Altbestellungen (verifiziert 2026-08-10) ----------
  kShopAlt: 3,                       // migrierter WooCommerce-Shop
  bestellnummerFeld: 'cBestellNr',   // entspricht Shopify order.name (ohne '#')
  shopifyNamePrefix: '',

  // --- Shopify ----------------------------------------------------------
  shop: 'vdzvc0-nd',
  apiVersion: '2024-10',
  batchGroesse: 25,                  // Bestellungen pro GraphQL-Sammelabfrage
  foProBestellung: 5,                // erwartete FulfillmentOrders je Bestellung

  // --- Betrieb ----------------------------------------------------------
  testLimit: 5,        // 0 = alle Kandidaten; >0 = nur die ersten N (Testbetrieb)
  dryRun: true,        // true = KEIN Schreib-Call an Shopify
  notifyCustomer: false,
  trackingSenden: false,
  auditTagSetzen: false,
  reportMailSenden: false,
  reportEmpfaenger: 'jesse.balsam@buecherbuechse.de'
};

return [{ json: { config: CONFIG } }];

// JTL-Zeilen -> schlanke Kandidatenobjekte fuer den Shopify-Lookup.
const config = $('Config').first().json.config;

let rows = $input.all().map(i => i.json).filter(r => r && r.kBestellung !== undefined);

if (config.testLimit > 0) rows = rows.slice(0, config.testLimit);

return rows.map(k => {
  const bestellnummer = String(k[config.bestellnummerFeld] ?? '').trim();
  return {
    json: {
      kBestellung:      Number(k.kBestellung),
      bestellnummer,
      shopifyOrderName: config.shopifyNamePrefix + bestellnummer,
      lieferscheine:    k.cLieferscheine ?? null,
      dVersendetMax:    k.dVersendetMax ?? null,
      positionen:       k.PositionenRelevant ?? null,
      trackingNummer:   (String(k.cIdentCodes ?? '').split(',')[0] || null),
      trackingCarrier:  (String(k.cLogistiker ?? '').trim() || null),
      runId:            $execution.id
    }
  };
});

// Kandidaten in Gruppen schneiden – eine GraphQL-Abfrage je Gruppe.
const config = $('Config').first().json.config;
const alle   = $input.all().map(i => i.json);
const groesse = Math.max(1, Math.min(Number(config.batchGroesse) || 25, 100));

const out = [];
for (let i = 0; i < alle.length; i += groesse) {
  out.push({ json: {
    batchIndex: out.length,
    batchGroesse: groesse,
    anzahl: alle.slice(i, i + groesse).length,
    kandidaten: alle.slice(i, i + groesse)
  }});
}
return out;

// Sammel-Lookup: eine Abfrage fuer alle Bestellnummern des Batches.
// Bewusst OHNE lineItems – wir fulfillen immer die komplette FulfillmentOrder,
// das haelt die GraphQL-Kosten niedrig.
const config = $('Config').first().json.config;
const batch  = $input.first().json;

const namen = batch.kandidaten.map(k => k.shopifyOrderName);
const q     = namen.map(n => 'name:' + n).join(' OR ');

const query = `query($q: String!) {
  orders(first: ${Math.max(1, batch.anzahl)}, query: $q) {
    edges { node {
      id
      name
      closed
      cancelledAt
      displayFulfillmentStatus
      fulfillmentOrders(first: ${config.foProBestellung}) {
        edges { node { id status } }
      }
    } }
  }
}`;

return [{ json: {
  batchIndex: batch.batchIndex,
  anzahl: batch.anzahl,
  kandidaten: batch.kandidaten,
  gqlBody: JSON.stringify({ query, variables: { q } })
}}];

// Antwort auf die Kandidaten des Batches zurueckmappen.
// Ein Ausgabe-Item je Kandidat, mit Entscheidung.
const config = $('Config').first().json.config;
const src    = $('Query bauen (Orders-Lookup)').first().json;
const resp   = $input.first().json;

const FO_OFFEN = ['OPEN', 'IN_PROGRESS', 'SCHEDULED'];

// Harter Fehler: ganzer Batch bekommt error
if (resp?.error || resp?.errors) {
  const msg = 'Orders-Lookup fehlgeschlagen: ' +
              JSON.stringify(resp.error || resp.errors).slice(0, 500);
  return src.kandidaten.map(k => ({ json: {
    ...k, batchIndex: src.batchIndex, shopifyStatus: 'error',
    shopifyAktion: 'skip', shopifyMessage: msg } }));
}

const gefunden = new Map();
for (const e of (resp?.data?.orders?.edges || [])) {
  gefunden.set(String(e.node.name).replace(/^#/, '').trim(), e.node);
}

return src.kandidaten.map(k => {
  const basis = { ...k, batchIndex: src.batchIndex };
  const raus  = (status, message, extra = {}) => ({ json: {
    ...basis, shopifyAktion: 'skip', shopifyStatus: status,
    shopifyMessage: message, ...extra } });

  const order = gefunden.get(String(k.shopifyOrderName).trim());
  if (!order) return raus('skipped_not_found',
    'Keine Shopify-Bestellung mit name=' + k.shopifyOrderName);

  const extra = { shopifyOrderId: order.id, shopifyOrderClosed: order.closed,
                  shopifyFulfillmentStatus: order.displayFulfillmentStatus };

  if (order.cancelledAt) return raus('skipped_cancelled', 'Bestellung storniert', extra);
  if (order.displayFulfillmentStatus === 'FULFILLED')
    return raus('skipped_already_fulfilled', 'Bereits fulfilled', extra);

  const fos = (order.fulfillmentOrders?.edges || [])
    .map(e => e.node).filter(n => FO_OFFEN.includes(n.status));

  if (!fos.length) return raus('skipped_no_fulfillment_order',
    'Keine offene FulfillmentOrder (Status: ' + order.displayFulfillmentStatus + ')', extra);

  return { json: {
    ...basis, ...extra,
    shopifyAktion:       config.dryRun ? 'dry_run' : 'create',
    shopifyStatus:       config.dryRun ? 'ready_dry_run' : 'ready',
    shopifyMessage:      null,
    fulfillmentOrderIds: fos.map(f => f.id),
    fulfillmentOrderStatus: fos.map(f => f.status)
  }};
});

// Body fuer fulfillmentCreate. Ohne lineItems = alle offenen Positionen der FO.
const config = $('Config').first().json.config;
const item   = $input.first().json;

const fulfillment = {
  notifyCustomer: config.notifyCustomer,
  lineItemsByFulfillmentOrder: item.fulfillmentOrderIds.map(id => ({ fulfillmentOrderId: id }))
};

if (config.trackingSenden && item.trackingNummer) {
  fulfillment.trackingInfo = {
    number:  item.trackingNummer,
    company: item.trackingCarrier || 'DHL'
  };
}

const body = {
  query: `mutation fulfillmentCreate($fulfillment: FulfillmentInput!) {
    fulfillmentCreate(fulfillment: $fulfillment) {
      fulfillment { id status createdAt }
      userErrors { field message }
    }
  }`,
  variables: { fulfillment }
};

return [{ json: { ...item, gqlBody: JSON.stringify(body) } }];

const src  = $('⚠️ Query bauen (fulfillmentCreate)').item.json;
const resp = $input.first().json;

if (resp?.error || resp?.errors) {
  return [{ json: { ...src, shopifyStatus: 'error',
    shopifyMessage: 'HTTP/GraphQL-Fehler: ' + JSON.stringify(resp.error || resp.errors).slice(0, 500) } }];
}

const res  = resp?.data?.fulfillmentCreate;
const errs = res?.userErrors || [];
if (errs.length) {
  return [{ json: { ...src, shopifyStatus: 'error',
    shopifyMessage: 'userErrors: ' + JSON.stringify(errs) } }];
}

return [{ json: { ...src, shopifyStatus: 'done', shopifyMessage: null,
                  shopifyFulfillmentId: res?.fulfillment?.id || null } }];

// Auswertung ueber alle Batches. Kein DB-Schreibzugriff.
const config = $('Config').first().json.config;
const items  = $input.all().map(i => i.json);

const zaehler = {};
for (const i of items) zaehler[i.shopifyStatus] = (zaehler[i.shopifyStatus] || 0) + 1;

const nichtGefunden = items.filter(i => i.shopifyStatus === 'skipped_not_found')
                           .map(i => i.bestellnummer);
const fehler        = items.filter(i => i.shopifyStatus === 'error')
                           .map(i => ({ nr: i.bestellnummer, msg: i.shopifyMessage }));

const zusammenfassung = {
  runId: $execution.id,
  dryRun: config.dryRun,
  testLimit: config.testLimit,
  kandidatenGesamt: items.length,
  proStatus: zaehler,
  bereitZumFulfillen: (zaehler.ready || 0) + (zaehler.ready_dry_run || 0),
  nichtGefundenBeispiele: nichtGefunden.slice(0, 20),
  fehlerBeispiele: fehler.slice(0, 20)
};

const zeilen = Object.entries(zaehler)
  .map(([k, v]) => '<tr><td>' + k + '</td><td align="right">' + v + '</td></tr>').join('');

return [{ json: {
  ...zusammenfassung,
  detail: items,
  titel: 'JTL -> Shopify Fulfillment (Lookup) – Run ' + $execution.id,
  sendto: config.reportEmpfaenger,
  mailText: '<h3>JTL &rarr; Shopify Fulfillment (Lookup)</h3>' +
            '<p>Dry-Run: <b>' + config.dryRun + '</b>, Kandidaten: <b>' + items.length + '</b></p>' +
            '<table border="1" cellpadding="4" cellspacing="0">' + zeilen + '</table>'
}}];
